// 3) RTL test: NumberInput-readonly.test.js
import React from 'react';
import { render } from '@testing-library/react';
import '@testing-library/jest-dom/extend-expect';
import { NumberInput } from 'carbon-components-react';

test('renders NumberInput in read-only state', () => {
  const { getByRole, container } = render(
    <NumberInput
      id="test-readonly"
      label="Test read-only"
      defaultValue={42}
      helperText="Helper text"
      readOnly
    />
  );

  const input = getByRole('spinbutton');
  // native attribute
  expect(input).toHaveAttribute('readonly');
  // CSS modifier class
  expect(input).toHaveClass('bx--number__input--readonly');

  // buttons should be disabled
  const buttons = container.querySelectorAll('.bx--number__control-btn');
  buttons.forEach((btn) => {
    expect(btn).toHaveAttribute('disabled');
    expect(btn).toHaveClass('bx--number__control-btn--readonly');
  });
});
